SELECT a.id,a.title,a.summary,a.category_id,COALESCE(c.name,'未知分类') AS category_name,
    a.author_id,a.status,a.version,a.created_at,a.updated_at,a.published_at
FROM cms_article a LEFT JOIN cms_category c ON c.id=a.category_id AND c.deleted=0
WHERE a.deleted=0
AND a.title LIKE #{titlePattern} ESCAPE '!'
AND a.category_id=#{query.categoryId}
AND a.status=#{query.status}
AND a.author_id=#{query.authorId}
AND a.created_at >= #{createdStart}
AND a.created_at < #{createdEnd}
AND a.updated_at >= #{updatedStart}
AND a.updated_at < #{updatedEnd}
ORDER BY

    a.created_at
    a.published_at
    a.title
    a.updated_at

ASC, a.id ASCDESC, a.id DESC

mapper.update:
UPDATE cms_article SET title=#{row.title}, summary=#{row.summary,jdbcType=VARCHAR}, content=#{row.content},
    category_id=#{row.categoryId}, version=version+1, updated_by=#{row.updatedBy}, updated_at=#{row.updatedAt}
WHERE id=#{row.id} AND version=#{row.version} AND status=#{row.status}
  AND status IN ('DRAFT','REJECTED') AND deleted=0

UPDATE cms_article SET deleted=1, version=version+1, updated_by=#{row.updatedBy}, updated_at=#{row.updatedAt}
WHERE id=#{row.id} AND version=#{row.version} AND status=#{row.status}
  AND status IN ('DRAFT','REJECTED','OFFLINE') AND deleted=0
